async def run_test(page, output_dir, page_url):
    from pathlib import Path
    try:
        await page.set_viewport_size({'width':390,'height':844})
        await page.goto('https://fileforge-workspace--8ei512uo.preview.emergentagent.com', wait_until='networkidle')
        assert await page.get_by_role('banner').get_by_test_id('brand-home-link').is_visible(); print('PASS: mobile home loads')
        await page.get_by_test_id('mobile-menu-button').click(); await page.get_by_test_id('mobile-all-tools-link').scroll_into_view_if_needed(); await page.get_by_test_id('mobile-all-tools-link').click(); await page.wait_for_url('**/tools'); assert await page.get_by_text('All tools', exact=True).is_visible(); print('PASS: mobile All Tools routes to /tools')
        await page.goto('https://fileforge-workspace--8ei512uo.preview.emergentagent.com', wait_until='networkidle'); await page.get_by_test_id('file-upload-zone').locator('input[type=file]').set_input_files('/app/test_reports/ui/test-image.png'); await page.get_by_test_id('nav-history-link').click(); assert await page.get_by_text('Your history is clear', exact=True).is_visible(); print('PASS: home upload does not create history')
        await page.goto('https://fileforge-workspace--8ei512uo.preview.emergentagent.com/tool/compress-image', wait_until='networkidle'); await page.get_by_test_id('file-upload-zone').locator('input[type=file]').set_input_files('/app/test_reports/ui/test-image.png'); await page.get_by_test_id('process-tool-button').click(); await page.wait_for_selector('[data-testid="download-ready"]', timeout=5000); assert 'Result ready' in (await page.get_by_test_id('download-ready').text_content()); print('PASS: image processing creates real canvas result'); await page.get_by_test_id('download-result-button').click()
        await page.goto('https://fileforge-workspace--8ei512uo.preview.emergentagent.com/history', wait_until='networkidle'); assert await page.get_by_text('test-image.png', exact=True).is_visible(); print('PASS: processed image creates history')
        await page.goto('https://fileforge-workspace--8ei512uo.preview.emergentagent.com/tool/merge-pdf', wait_until='networkidle'); await page.get_by_test_id('file-upload-zone').locator('input[type=file]').set_input_files('/app/test_reports/ui/test-image.png'); await page.get_by_test_id('process-tool-button').click(); assert await page.get_by_test_id('tool-error-message').is_visible() and not await page.get_by_test_id('download-ready').is_visible(); print('PASS: non-image processing has no fake download')
        await page.goto('https://fileforge-workspace--8ei512uo.preview.emergentagent.com/tools', wait_until='networkidle'); await page.get_by_test_id('tools-search-input').fill('JSON'); assert await page.get_by_test_id('tool-card-json-formatter').is_visible(); print('PASS: directory search works')
        await page.get_by_test_id('nav-settings-link').click(); await page.get_by_test_id('motion-toggle').click(); print('PASS: settings toggle works')
        overflow=await page.evaluate('document.documentElement.scrollWidth > document.documentElement.clientWidth'); print('PASS: no mobile horizontal overflow' if not overflow else 'FINDING: mobile horizontal overflow')
        errors=await page.evaluate("""() => Array.from(document.querySelectorAll('.error, [class*="error"], [id*="error"]')).map(el => el.textContent).join(', ')"""); print('Found error message: '+errors if errors else 'No error messages found on the page')
    except AssertionError as e: print('FINDING: assertion failed: '+str(e))
    except Exception as e: print('SCRIPT ERROR: '+str(e)); raise
